import { getNotificationPreference, toggleNotificationPreference } from './actions';

export default async function Home() {
  // Simulate a user ID (in a real app, this would come from auth)
  const userId = 'user-123';

  // Get the current notification preference
  const notificationsEnabled = await getNotificationPreference(userId);

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Settings</h1>

      <form action={async () => {
        'use server';
        await toggleNotificationPreference(userId);
      }}>
        <div style={{ marginTop: '1rem', display: 'flex', alignItems: 'center', gap: '1rem' }}>
          <label htmlFor="notifications">
            Notifications: <strong>{notificationsEnabled ? 'ON' : 'OFF'}</strong>
          </label>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              cursor: 'pointer',
              backgroundColor: notificationsEnabled ? '#dc3545' : '#28a745',
              color: 'white',
              border: 'none',
              borderRadius: '4px'
            }}
          >
            Turn {notificationsEnabled ? 'OFF' : 'ON'}
          </button>
        </div>
      </form>

      <p style={{ marginTop: '1rem', color: '#666' }}>
        Click the button to toggle your notification preference.
        The page will refresh to show the updated state.
      </p>
    </main>
  );
}

